python3 -c 'import re,sys
acc={};fail={};last={};lock=set();users=set()
for l in open('"'"'/home/user/logs/auth.log'"'"'):
    ts=re.match(r'"'"'^(\S+\s+\d+\s+\d\d:\d\d:\d\d)'"'"',l)
    m=re.search(r'"'"'Accepted password for (\S+)'"'"',l)
    if m:
        u=m.group(1);users.add(u);acc[u]=acc.get(u,0)+1
        if ts: last[u]=ts.group(1)
    m=re.search(r'"'"'Failed password for (\S+)'"'"',l)
    if m:
        u=m.group(1);users.add(u);fail[u]=fail.get(u,0)+1
    m=re.search(r'"'"'ACCOUNT LOCKED: (\S+)'"'"',l)
    if m:
        u=m.group(1);users.add(u);lock.add(u)
exp=['"'"'%s,%d,%d,%s,%s'"'"'%(u,acc.get(u,0),fail.get(u,0),last.get(u,'"'"'-'"'"'),'"'"'yes'"'"' if u in lock else '"'"'no'"'"') for u in sorted(users)]
sys.exit(0 if open('"'"'/home/user/reports/user_login_report.csv'"'"').read().splitlines()[1:]==exp else 1)'
